// ai-agents/metrics/src/survey-compare.ts  (npx tsx metrics/src/survey-compare.ts october.csv december.csv)
// October vs. December survey, team level only. Groups under 5 answers fold into 'Other'.
import { readFileSync } from "node:fs";
import { parse } from "csv-parse/sync"; // Google Forms answers can hold commas and quotes
import { median, quantile } from "./stats.js"; // quantile uses the same method as Python's statistics.quantiles

const MIN_GROUP = 5;
const HOURS: Record<string, number> = { "0": 0, "under 1 h": 0.5, "1-3 h": 2, "3-6 h": 4.5, "more than 6 h": 7 };
const QUESTIONS = ["time_saved", "lost_builds", "lost_review", "lost_setup", "lost_finding", "confident_change", "confident_ci"];
type Row = Record<string, string | undefined>;

function load(path: string): Map<string, Row[]> {
  const groups = new Map<string, Row[]>();
  for (const row of parse<Row>(readFileSync(path, "utf8"), { columns: true })) {
    const team = row.team ?? "Other";
    groups.set(team, [...(groups.get(team) ?? []), row]);
  }
  const keep = new Map([...groups].filter(([team, rows]) => rows.length >= MIN_GROUP && team !== "Other"));
  keep.set("Other", [...groups].filter(([team]) => !keep.has(team)).flatMap(([, rows]) => rows));
  return keep;
}

function summary(rows: Row[], question: string): string {
  const values = rows.flatMap((r) => { const a = r[question]; return a ? [HOURS[a] ?? Number(a[0])] : []; }); // agree: its digit
  if (values.length < MIN_GROUP) return "too few answers";
  const [mid, q1, q3] = [median(values), quantile(values, 0.25), quantile(values, 0.75)];
  return `median ${mid.toFixed(1)} (IQR ${q1.toFixed(1)}-${q3.toFixed(1)}, n=${values.length})`;
}
const [october, december] = [load(process.argv[2] ?? ""), load(process.argv[3] ?? "")];
for (const question of QUESTIONS) {
  for (const team of [...october.keys()].filter((t) => december.has(t)).sort()) {
    const oct = summary(october.get(team) ?? [], question), dec = summary(december.get(team) ?? [], question);
    console.log(`${question.padEnd(17)} ${team.padEnd(12)} Oct ${oct.padEnd(34)} Dec ${dec}`);
  }
}

